CREATE TABLE app_user (id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, display_name VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE project (id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES app_user(id), title VARCHAR(180) NOT NULL, description TEXT NOT NULL DEFAULT '', status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE chapter (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES project(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, position INTEGER NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(project_id, position));
CREATE TABLE document (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES project(id) ON DELETE CASCADE, chapter_id UUID REFERENCES chapter(id) ON DELETE SET NULL, title VARCHAR(180) NOT NULL, type VARCHAR(30) NOT NULL, content TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE document_version (id UUID PRIMARY KEY, document_id UUID NOT NULL REFERENCES document(id) ON DELETE CASCADE, revision INTEGER NOT NULL, title VARCHAR(180) NOT NULL, content TEXT NOT NULL, created_by VARCHAR(30) NOT NULL DEFAULT 'CREATOR', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(document_id, revision));
CREATE INDEX idx_project_owner ON project(owner_id); CREATE INDEX idx_document_project ON document(project_id); CREATE INDEX idx_version_document ON document_version(document_id);
